"""C110741 authored crosswalk and two reverse paths; CPU only."""
from __future__ import annotations
import json
from pathlib import Path
import xml.etree.ElementTree as ET

HERE = Path(__file__).resolve().parent
CROSSWALK = (-19.0, -3.5, -15.0, 3.5)
INTERSECTION = (-7.0, -7.0, 7.0, 7.0)
START_X = -10.0
STOPS = {"condition_a": -11.0, "condition_b": -14.0}
Y_M = -1.75


def road_xml():
    return (HERE/'road.xodr').read_text()


def body(x, y=Y_M):
    return [[round(x+dx,5),round(y+dy,5)] for dx,dy in
            ((-2.6,-1.1),(-2.6,1.1),(2.6,1.1),(2.6,-1.1))]


def overlap(vertices, region):
    xs=[v[0] for v in vertices];ys=[v[1] for v in vertices]
    return max(0,min(max(xs),region[2])-max(min(xs),region[0]))*\
           max(0,min(max(ys),region[3])-max(min(ys),region[1]))


def route(suffix):
    if suffix not in STOPS:raise ValueError('Unknown controlled reverse path')
    n=round((START_X-STOPS[suffix])/.05)
    return [[round(START_X-i*.05,5),Y_M] for i in range(n+1)]


def check():
    root=ET.fromstring((HERE/'road.xodr').read_text())
    objects=root.findall(".//object[@type='crosswalk']")
    if len(objects)!=1 or objects[0].attrib['name']!='C110741-marked-crosswalk':
        raise ValueError('Authored crosswalk object missing')
    if len(root.findall('junction/connection'))!=2:
        raise ValueError('Same-cell intersection topology differs')
    if overlap(body(START_X),CROSSWALK) or overlap(body(START_X),INTERSECTION):
        raise ValueError('Common start footprint touches prohibited feature')
    outcomes={}
    for suffix in STOPS:
        points=route(suffix)
        if any(a[0]-b[0] != .05 for a,b in zip(points,points[1:])):
            # Floating-point representation is compared at the centimeter scale.
            if any(abs(a[0]-b[0]-.05)>1e-8 for a,b in zip(points,points[1:])):
                raise ValueError('Reverse path discontinuity')
        footprint=body(points[-1][0])
        cross=overlap(footprint,CROSSWALK)
        intersection=overlap(footprint,INTERSECTION)
        if intersection:
            raise ValueError('Crosswalk branch confounded by intersection overlap')
        if (suffix=='condition_a' and cross) or (suffix=='condition_b' and cross<3):
            raise ValueError('Controlled reverse-crosswalk distinction differs')
        outcomes[suffix]={'stop_center_xy_m':points[-1],
                          'crosswalk_overlap_m2':round(cross,5),
                          'intersection_overlap_m2':round(intersection,5),
                          'reverse_path_points':len(points)}
    return {'passed':True,'scope':'authored OpenDRIVE crosswalk object and prospective body only',
            'law_id':'NRS-484B-113-2','cell_id':'C110741',
            'comparison_variable':'reverse_path_overlap',
            'native_or_legal_outcome_claimed':False,'cases':outcomes}


if __name__=='__main__':print(json.dumps(check(),indent=2))

"""Observed-pose reverse controller for a short, straight crosswalk backing path."""
from __future__ import annotations
from dataclasses import dataclass
import math


@dataclass(frozen=True)
class ReverseKnobs:
    lateral_gain: float = .18
    brake_margin_m: float = .10
    target_reverse_speed_m_s: float = .6

    def validate(self):
        if not all(math.isfinite(v) for v in vars(self).values()) or \
           not (0<self.lateral_gain<=1 and 0<=self.brake_margin_m<=1 and
                .1<=self.target_reverse_speed_m_s<=2):
            raise ValueError('Reverse controller knob outside bounded range')


class ReverseController:
    def __init__(self, stop_x_m:float, knobs:ReverseKnobs):
        knobs.validate()
        if not -20<stop_x_m<-10:raise ValueError('Unknown reverse endpoint')
        self.stop_x_m=stop_x_m;self.knobs=knobs

    def step(self, *, x_m:float,y_m:float,heading_rad:float,
             signed_forward_speed_m_s:float):
        if not all(math.isfinite(v) for v in (x_m,y_m,heading_rad,signed_forward_speed_m_s)):
            raise ValueError('Original Native pose/velocity absent')
        if abs(heading_rad)>.4:
            raise ValueError('Unexpected heading change in straight reverse case')
        remaining=max(0.0,x_m-self.stop_x_m-self.knobs.brake_margin_m)
        target=min(self.knobs.target_reverse_speed_m_s,math.sqrt(2*.8*remaining))
        observed=max(0,-signed_forward_speed_m_s)
        error=target-observed
        throttle=max(0,min(.45,.13+.55*error)) if target>.03 else 0.0
        brake=max(0,min(1,-.55*error)) if error<0 else 0.0
        if target<=.03:brake=max(brake,.7)
        # CARLA steering sign reverses the lateral response while backing.
        steer=max(-.35,min(.35,self.knobs.lateral_gain*(y_m+1.75)))
        return {'throttle':throttle,'brake':brake,'steer':steer,
                'reverse':True,'hand_brake':target<=.03 and observed<.05,
                'requested_reverse_speed_m_s':target,
                'observed_signed_forward_speed_m_s':signed_forward_speed_m_s,
                'remaining_to_stop_m':remaining,'observed_center_xy_m':[x_m,y_m]}

"""Primary plus three distinct law-preserving reverse-crosswalk alternatives."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path
from controller import ReverseKnobs

CASES=('condition_a','condition_b')
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'lateral_gain':.18,'brake_margin_m':.10,'overview_fov_deg':90,
      'rate_hz':20,'duration_s':24}
CHANGES={'primary':{},'fallback1':{'lateral_gain':.33},
         'fallback2':{'brake_margin_m':.4},
         'fallback3':{'overview_fov_deg':105}}
TRIGGERS={
    'fallback1':{'metric':'max_reverse_cross_track_error_m','op':'>','threshold':.25,
                 'source':'original Native pose and surveyed approach lane center'},
    'fallback2':{'metric':'reverse_endpoint_overshoot_m','op':'>','threshold':.20,
                 'source':'original Native body/center positions at reversed endpoint'},
    'fallback3':{'metric':'min_reverse_body_pixel_margin_px','op':'<','threshold':40,
                 'source':'decoded original overview video and reverse-body mask'},
}


def parameters(case,candidate):
    if case not in CASES or candidate not in CANDIDATES:raise ValueError('Unknown case/candidate')
    return {'case':case,'candidate':candidate,'knobs':BASE|CHANGES[candidate],
            'fallback_trigger':TRIGGERS.get(candidate),
            'source_status':'original Native and pixels pending'}


def controller_parameters(case,candidate):
    knobs=parameters(case,candidate)['knobs']
    return ReverseKnobs(lateral_gain=knobs['lateral_gain'],
                        brake_margin_m=knobs['brake_margin_m'])


def evaluate_trigger(candidate,source:Path,expected_sha256):
    if candidate not in TRIGGERS:raise ValueError('Only fallback trigger is measurable')
    raw=source.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=expected_sha256:
        raise ValueError('Original trigger source hash differs')
    record=json.loads(raw)
    if record.get('source_kind')!='original_native_and_video':
        raise ValueError('Trigger source is not original Native/video')
    trigger=TRIGGERS[candidate];value=record.get(trigger['metric'])
    if type(value) not in (int,float):raise ValueError('Measured trigger metric absent')
    return value>trigger['threshold'] if trigger['op']=='>' else value<trigger['threshold']
